export enum EvaluationStatus {
  EXCELLENT = 'Hoàn thành tốt',
  COMPLETE = 'Hoàn thành',
  INCOMPLETE = 'Chưa hoàn thành',
  UNKNOWN = 'Chưa đánh giá'
}

export interface AnalysisResult {
  markdownText: string;
  evaluation: EvaluationStatus;
}

export interface TechniqueStep {
  title: string;
  description: string[];
}

export interface TechniquePhase {
  name: string;
  steps: TechniqueStep[];
}

import { GoogleGenAI } from "@google/genai";
import { EvaluationStatus, AnalysisResult } from '../types';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const SYSTEM_PROMPT = `
Bạn là một huấn luyện viên Giáo dục Thể chất chuyên nghiệp, chuyên về bộ môn Ném bóng.
Nhiệm vụ của bạn là phân tích hình ảnh hoặc video của học sinh thực hiện kỹ thuật ném bóng dựa trên tiêu chuẩn sau:

Giai đoạn 1: Chuẩn bị tư vấn:
– Đứng 2 chân trước sau, rộng bằng vai, chân không thuận đặt phía trước.
– Trọng tâm dồn đều 2 chân.
– Hai tay cầm bóng trước ngực.
– Mắt nhìn về hướng Ném.

Giai đoạn 2: Thực hiện tác vụ Ném bóng.
Bước 1: Xoay thân và đưa bóng lên vai.
– Từ tư thế chuẩn bị xoay thân cho vai không thuận hướng về hướng Ném (ném tay phải thì vai trái hướng về hướng Ném).
– Hai tay phối hợp nhịp nhàng đưa bóng ra sau - lên trên vai, lúc này tay thuận cầm bóng, tay trái hướng về hướng ném để giữ thăng bằng.
Bước 2: Xoay hông và ném bóng.
– Thực hiện xoay hông đồng thời thực hiện động tác vung tay Ném bóng về hướng cần Ném.
– Kết thúc bước chân sau lên trước để giữ thăng bằng.

Hãy phân tích kỹ thuật của học sinh và trả về kết quả theo định dạng Markdown tiếng Việt:
1. **Những điểm thực hiện đúng**: Liệt kê chi tiết.
2. **Những điểm sai**: Liệt kê chi tiết những lỗi sai so với kỹ thuật chuẩn.
3. **Hướng dẫn giải quyết và cách khắc phục**: Đưa ra bài tập hoặc lời khuyên cụ thể.
4. **Đánh giá chung**: Chỉ ghi chính xác một trong 3 cụm từ sau ở dòng cuối cùng: "Hoàn thành tốt", "Hoàn thành", hoặc "Chưa hoàn thành".
`;

export const analyzeTechnique = async (
  mediaBase64: string,
  mimeType: string
): Promise<AnalysisResult> => {
  try {
    const modelId = 'gemini-2.5-flash-latest'; // Supports video and images effectively

    const response = await ai.models.generateContent({
      model: modelId,
      contents: {
        parts: [
          {
            text: SYSTEM_PROMPT,
          },
          {
            inlineData: {
              data: mediaBase64,
              mimeType: mimeType,
            },
          },
        ],
      },
    });

    const text = response.text || "";

    // Extract evaluation from text
    let evaluation = EvaluationStatus.UNKNOWN;
    if (text.toLowerCase().includes('hoàn thành tốt')) {
      evaluation = EvaluationStatus.EXCELLENT;
    } else if (text.toLowerCase().includes('chưa hoàn thành')) {
      evaluation = EvaluationStatus.INCOMPLETE;
    } else if (text.toLowerCase().includes('hoàn thành')) {
      evaluation = EvaluationStatus.COMPLETE;
    }

    return {
      markdownText: text,
      evaluation: evaluation,
    };
  } catch (error) {
    console.error("Gemini Analysis Error:", error);
    throw new Error("Không thể phân tích dữ liệu. Vui lòng thử lại.");
  }
};

