import React from 'react';
import ReactMarkdown from 'react-markdown';
import { AnalysisResult, EvaluationStatus } from '../types';
import { Volume2, Download, RefreshCw, AlertCircle, CheckCircle2 } from 'lucide-react';

interface AnalysisDisplayProps {
  result: AnalysisResult | null;
  loading: boolean;
  onSpeak: () => void;
  onExport: () => void;
  onReset: () => void;
}

const AnalysisDisplay: React.FC<AnalysisDisplayProps> = ({ 
  result, 
  loading, 
  onSpeak, 
  onExport, 
  onReset 
}) => {

  const getStatusColor = (status: EvaluationStatus) => {
    switch (status) {
      case EvaluationStatus.EXCELLENT: return 'bg-green-100 text-green-800 border-green-300';
      case EvaluationStatus.COMPLETE: return 'bg-blue-100 text-blue-800 border-blue-300';
      case EvaluationStatus.INCOMPLETE: return 'bg-red-100 text-red-800 border-red-300';
      default: return 'bg-gray-100 text-gray-800 border-gray-300';
    }
  };

  return (
    <div className="bg-white rounded-lg shadow-sm border border-gray-200 h-full flex flex-col">
      <div className="bg-green-700 p-3 text-white flex justify-between items-center rounded-t-lg">
        <h2 className="text-lg font-bold uppercase">Kết Quả Phân Tích & Đánh Giá</h2>
        <div className="flex gap-2">
           <button onClick={onExport} className="p-1.5 hover:bg-green-600 rounded-full transition-colors" title="Xuất hình ảnh">
             <Download size={20} />
           </button>
           <button onClick={onReset} className="p-1.5 hover:bg-green-600 rounded-full transition-colors" title="Làm mới">
             <RefreshCw size={20} />
           </button>
        </div>
      </div>

      <div className="flex-grow p-6 overflow-y-auto relative">
        {loading ? (
          <div className="flex flex-col items-center justify-center h-full text-gray-500 space-y-4">
            <div className="w-12 h-12 border-4 border-green-600 border-t-transparent rounded-full animate-spin"></div>
            <p className="animate-pulse font-medium">Đang phân tích dữ liệu...</p>
          </div>
        ) : !result ? (
          <div className="flex flex-col items-center justify-center h-full text-gray-400 space-y-4 text-center">
            <AlertCircle size={48} className="opacity-50" />
            <p>Vui lòng nhập hình ảnh hoặc video để bắt đầu phân tích.</p>
          </div>
        ) : (
          <div className="space-y-6">

            {/* Markdown Content */}
            <div className="prose prose-sm max-w-none prose-headings:text-green-800 prose-strong:text-gray-900 prose-li:text-gray-700">
               <ReactMarkdown>{result.markdownText}</ReactMarkdown>
            </div>

            {/* Evaluation Badge */}
            <div className="border-t pt-4 mt-4">
               <div className="flex flex-col items-center justify-center space-y-2">
                 <span className="text-sm font-semibold text-gray-500 uppercase">Đánh giá chung</span>
                 <span className={`px-6 py-2 rounded-full text-lg font-bold border-2 ${getStatusColor(result.evaluation)}`}>
                    {result.evaluation}
                 </span>
               </div>
            </div>

            {/* Action Buttons */}
            <div className="flex flex-wrap gap-4 justify-center mt-6 pt-4 border-t border-gray-100">
              <button 
                onClick={onSpeak}
                className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition shadow-sm"
              >
                <Volume2 size={18} />
                Đọc kết quả
              </button>

              <button 
                onClick={onExport}
                className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition shadow-sm"
              >
                <Download size={18} />
                Xuất JPG
              </button>
            </div>

          </div>
        )}
      </div>
    </div>
  );
};

export default AnalysisDisplay;

import React, { useState, useRef } from 'react';
import Header from './components/Header';
import TechniqueStandard from './components/TechniqueStandard';
import AnalysisDisplay from './components/AnalysisDisplay';
import { analyzeTechnique } from './services/geminiService';
import { AnalysisResult } from './types';
import html2canvas from 'html2canvas';
import { Upload, Camera, Video, Image as ImageIcon } from 'lucide-react';

const App: React.FC = () => {
  const [mediaUrl, setMediaUrl] = useState<string | null>(null);
  const [mediaType, setMediaType] = useState<'image' | 'video' | null>(null);
  const [analysisResult, setAnalysisResult] = useState<AnalysisResult | null>(null);
  const [loading, setLoading] = useState(false);

  const appRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Handle File Upload
  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    // Reset previous analysis
    setAnalysisResult(null);
    setLoading(true);

    const type = file.type.startsWith('video') ? 'video' : 'image';
    setMediaType(type);

    // Create Object URL for preview
    const url = URL.createObjectURL(file);
    setMediaUrl(url);

    try {
      // Convert file to base64 for Gemini
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onloadend = async () => {
        const base64String = reader.result as string;
        // Remove data URL prefix (e.g., "data:image/jpeg;base64,")
        const base64Data = base64String.split(',')[1];

        try {
          const result = await analyzeTechnique(base64Data, file.type);
          setAnalysisResult(result);
        } catch (error) {
          alert('Có lỗi xảy ra trong quá trình phân tích. Vui lòng thử lại.');
          console.error(error);
        } finally {
          setLoading(false);
        }
      };
    } catch (error) {
      console.error("File reading error:", error);
      setLoading(false);
    }
  };

  // Text to Speech
  const handleSpeak = () => {
    if (!analysisResult) return;
    const utterance = new SpeechSynthesisUtterance(analysisResult.markdownText.replace(/\*\*/g, '')); // Remove markdown bold syntax for smoother speech
    utterance.lang = 'vi-VN';
    window.speechSynthesis.cancel(); // Stop current speech
    window.speechSynthesis.speak(utterance);
  };

  // Export as JPG
  const handleExport = async () => {
    if (!appRef.current) return;
    try {
      const canvas = await html2canvas(appRef.current, {
        useCORS: true, // Important for images hosted externally
        scale: 2, // Higher quality
        logging: false,
      });
      const link = document.createElement('a');
      link.download = `phan-tich-ky-thuat-${new Date().toISOString().split('T')[0]}.jpg`;
      link.href = canvas.toDataURL('image/jpeg', 0.9);
      link.click();
    } catch (error) {
      console.error("Export failed:", error);
      alert("Không thể xuất hình ảnh. Vui lòng thử lại.");
    }
  };

  // Reset App
  const handleReset = () => {
    setMediaUrl(null);
    setMediaType(null);
    setAnalysisResult(null);
    setLoading(false);
    if (fileInputRef.current) fileInputRef.current.value = '';
    window.speechSynthesis.cancel();
  };

  return (
    <div className="min-h-screen flex flex-col" ref={appRef}>
      <Header />

      <main className="flex-grow p-4 md:p-6 grid grid-cols-1 md:grid-cols-2 gap-6 max-w-7xl mx-auto w-full">

        {/* LEFT COLUMN: Input & Standards */}
        <div className="flex flex-col gap-6">

          {/* Top: Input Section */}
          <div className="bg-white p-4 rounded-lg shadow-sm border border-gray-200">
             <div className="flex flex-col sm:flex-row gap-4 mb-4">
                <input 
                  type="file" 
                  ref={fileInputRef}
                  onChange={handleFileUpload} 
                  accept="image/*,video/*" 
                  className="hidden" 
                  id="media-upload"
                />
                <label 
                  htmlFor="media-upload" 
                  className="flex-1 cursor-pointer bg-blue-600 hover:bg-blue-700 text-white font-medium py-3 px-4 rounded-lg flex items-center justify-center gap-2 transition-colors shadow-sm"
                >
                  <Upload size={20} />
                  Nhập Hình ảnh / Video
                </label>

                <button 
                  className="flex-1 bg-gray-100 text-gray-400 font-medium py-3 px-4 rounded-lg flex items-center justify-center gap-2 cursor-not-allowed border border-dashed border-gray-300"
                  disabled
                  title="Chức năng đang phát triển"
                >
                  <Camera size={20} />
                  HLV Trực Tuyến AI (Sắp ra mắt)
                </button>
             </div>

             {/* Media Preview Area */}
             <div className="w-full bg-gray-900 rounded-lg overflow-hidden min-h-[250px] flex items-center justify-center relative border border-gray-800">
               {mediaUrl ? (
                  mediaType === 'video' ? (
                    <video src={mediaUrl} controls className="max-h-[400px] w-full object-contain" />
                  ) : (
                    <img src={mediaUrl} alt="Uploaded content" className="max-h-[400px] w-full object-contain" />
                  )
               ) : (
                 <div className="text-gray-500 flex flex-col items-center">
                   <div className="flex gap-4 mb-2">
                     <ImageIcon size={32} />
                     <Video size={32} />
                   </div>
                   <p>Dữ liệu hình ảnh/video sẽ hiển thị tại đây</p>
                 </div>
               )}
             </div>
          </div>

          {/* Body: Standards */}
          <div className="flex-grow">
            <TechniqueStandard />
          </div>

        </div>

        {/* RIGHT COLUMN: Analysis Results */}
        <div className="flex flex-col h-full">
          <AnalysisDisplay 
            result={analysisResult} 
            loading={loading}
            onSpeak={handleSpeak}
            onExport={handleExport}
            onReset={handleReset}
          />
        </div>

      </main>
    </div>
  );
};

export default App;

