                >
                  <Upload size={20} />
                  Nhập Hình ảnh / Video
                </label>

                <button 
                  className="flex-1 bg-gray-100 text-gray-400 font-medium py-3 px-4 rounded-lg flex items-center justify-center gap-2 cursor-not-allowed border border-dashed border-gray-300"
                  disabled
                  title="Chức năng đang phát triển"
                >
                  <Camera size={20} />
                  HLV Trực Tuyến AI (Sắp ra mắt)
