3. "overallAdvice": Lời khuyên tổng kết và bài tập bổ trợ.
4. "evaluation": Đánh giá xếp loại. Chỉ chọn 1 trong 3 giá trị: "Hoàn thành tốt", "Hoàn thành", "Chưa hoàn thành".

Hãy phân tích kỹ lưỡng và đưa ra nhận xét mang tính xây dựng, giọng điệu chuyên nghiệp của huấn luyện viên.
`;

export const analyzeTechnique = async (
  mediaBase64: string,
  mimeType: string
): Promise<AnalysisResult> => {
  try {
    const modelId = 'gemini-2.0-flash';

    const response = await ai.models.generateContent({
      model: modelId,
      contents: {
        parts: [
          { text: SYSTEM_PROMPT },
          { inlineData: { data: mediaBase64, mimeType: mimeType } },
        ],
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            summaryQuote: { type: Type.STRING },
            phases: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  phaseName: { type: Type.STRING },
                  score: { type: Type.NUMBER },
                  assessment: { type: Type.STRING },
                  errors: { 
                    type: Type.ARRAY, 
                    items: { type: Type.STRING } 
                  },
                  improvement: { type: Type.STRING }
                },
                required: ["phaseName", "score", "assessment", "errors", "improvement"]
              }
            },
            overallAdvice: { type: Type.STRING },
            evaluation: { 
              type: Type.STRING, 
              enum: ["Hoàn thành tốt", "Hoàn thành", "Chưa hoàn thành"] 
            }
          },
          required: ["summaryQuote", "phases", "overallAdvice", "evaluation"]
        }
      },
    });

    const jsonText = response.text || "{}";
    const data = JSON.parse(jsonText) as TechniqueAnalysis;

    // Map string evaluation to Enum
    let evalEnum = EvaluationStatus.UNKNOWN;
    if (data.evaluation === "Hoàn thành tốt") evalEnum = EvaluationStatus.EXCELLENT;
    else if (data.evaluation === "Hoàn thành") evalEnum = EvaluationStatus.COMPLETE;
    else if (data.evaluation === "Chưa hoàn thành") evalEnum = EvaluationStatus.INCOMPLETE;

    // Ensure evaluation enum is set correctly in the data object if needed for consistency
    // but primarily returning it in the AnalysisResult wrapper

    return {
      data: data,
      rawText: jsonText
    };

  } catch (error) {
    console.error("Gemini Analysis Error:", error);
    throw new Error("Không thể phân tích dữ liệu. Vui lòng thử lại.");
  }
};

