import React, { useState, useRef } from 'react';
import Header from './components/Header';
import TechniqueStandard from './components/TechniqueStandard';
import AnalysisDisplay from './components/AnalysisDisplay';
import { analyzeTechnique } from './services/geminiService';
import { AnalysisResult } from './types';
import html2canvas from 'html2canvas';
import { Upload, Camera, Video, Image as ImageIcon } from 'lucide-react';

const App: React.FC = () => {
  const [mediaUrl, setMediaUrl] = useState<string | null>(null);
  const [mediaType, setMediaType] = useState<'image' | 'video' | null>(null);
  const [analysisResult, setAnalysisResult] = useState<AnalysisResult | null>(null);
  const [loading, setLoading] = useState(false);

  const appRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Handle File Upload
  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    // Reset previous analysis
    setAnalysisResult(null);
    setLoading(true);

    const type = file.type.startsWith('video') ? 'video' : 'image';
    setMediaType(type);

    // Create Object URL for preview
    const url = URL.createObjectURL(file);
    setMediaUrl(url);

    try {
      // Convert file to base64 for Gemini
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onloadend = async () => {
        const base64String = reader.result as string;
        // Remove data URL prefix (e.g., "data:image/jpeg;base64,")
        const base64Data = base64String.split(',')[1];

        try {
          // Proceed to analyze immediately after input as requested
          const result = await analyzeTechnique(base64Data, file.type);
          setAnalysisResult(result);
        } catch (error) {
          alert('Có lỗi xảy ra trong quá trình phân tích. Vui lòng thử lại.');
          console.error(error);
        } finally {
          setLoading(false);
        }
      };
    } catch (error) {
      console.error("File reading error:", error);
      setLoading(false);
    }
  };

  // Text to Speech
  const handleSpeak = (textToRead?: string) => {
    if (!analysisResult?.data) return;

    let text = "";

    if (textToRead) {
      // Read specific text passed (e.g., single error or single phase assessment)
      text = textToRead;
    } else {
      // Read full report
      const data = analysisResult.data;
      text = `Tổng quan: ${data.summaryQuote}. `;

      data.phases.forEach((phase) => {
         text += `${phase.phaseName}. Điểm số ${phase.score} trên 10. ${phase.assessment}. `;
         if (phase.errors.length > 0) {
           text += `Các lỗi cần sửa: ${phase.errors.join('. ')}. `;
         }
         text += `Đề xuất: ${phase.improvement}. `;
      });

      text += `Tổng kết: ${data.overallAdvice}. Đánh giá chung: ${data.evaluation}.`;
    }

    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = 'vi-VN';

    // Cấu hình giọng đọc: Nhanh nhẹn (rate > 1) và Vui vẻ/Thể thao (pitch > 1)
    utterance.rate = 1.2; 
    utterance.pitch = 1.1;

    window.speechSynthesis.cancel(); // Stop current speech
    window.speechSynthesis.speak(utterance);
  };

  // Export as JPG
  const handleExport = async () => {
    if (!appRef.current) return;
    try {
      const canvas = await html2canvas(appRef.current, {
        useCORS: true, // Important for images hosted externally
        scale: 2, // Higher quality
        logging: false,
      });
      const link = document.createElement('a');
      link.download = `phan-tich-ky-thuat-${new Date().toISOString().split('T')[0]}.jpg`;
      link.href = canvas.toDataURL('image/jpeg', 0.9);
      link.click();
    } catch (error) {
      console.error("Export failed:", error);
      alert("Không thể xuất hình ảnh. Vui lòng thử lại.");
    }
  };

  // Reset App
  const handleReset = () => {
    setMediaUrl(null);
    setMediaType(null);
    setAnalysisResult(null);
    setLoading(false);
    if (fileInputRef.current) fileInputRef.current.value = '';
    window.speechSynthesis.cancel();
  };

  return (
    <div className="min-h-screen flex flex-col" ref={appRef}>
      <Header />

      <main className="flex-grow p-4 md:p-6 grid grid-cols-1 md:grid-cols-2 gap-6 max-w-7xl mx-auto w-full">

        {/* LEFT COLUMN: Input & Standards */}
        <div className="flex flex-col gap-6">

          {/* Top: Input Section */}
          <div className="bg-white p-4 rounded-lg shadow-sm border border-gray-200">
             <div className="flex flex-col sm:flex-row gap-4 mb-4">
                <input 
                  type="file" 
                  ref={fileInputRef}
                  onChange={handleFileUpload}
                  onClick={(e) => (e.currentTarget.value = '')} 
                  accept="image/*,video/*" 
                  className="hidden" 
                  id="media-upload"
                />
                <label 
                  htmlFor="media-upload" 
                  className="flex-1 cursor-pointer bg-blue-600 hover:bg-blue-700 text-white font-medium py-3 px-4 rounded-lg flex items-center justify-center gap-2 transition-colors shadow-sm"
                >
                  <Upload size={20} />
                  Nhập Hình ảnh / Video
                </label>

                <button 
                  className="flex-1 bg-gray-100 text-gray-400 font-medium py-3 px-4 rounded-lg flex flex-col items-center justify-center gap-1 cursor-not-allowed border border-dashed border-gray-300 text-center text-sm"
                  disabled
                  title="Chức năng đang phát triển"
                >
                  <div className="flex items-center gap-2">
                    <Camera size={20} />
                    <span>Huấn Luyện Viên trực tuyến AI</span>
                  </div>
                  <span className="text-xs italic">(tạm thời chưa hoạt động đến khi đạt thứ hạng cao)</span>
                </button>
             </div>

             {/* Media Preview Area */}
             <div className="w-full bg-gray-900 rounded-lg overflow-hidden min-h-[250px] flex items-center justify-center relative border border-gray-800">
               {mediaUrl ? (
                  mediaType === 'video' ? (
                    <video 
                      src={mediaUrl} 
                      controls 
                      className="max-h-[400px] w-full object-contain" 
                      playsInline
                    />
                  ) : (
                    <img src={mediaUrl} alt="Uploaded content" className="max-h-[400px] w-full object-contain" />
                  )
               ) : (
                 <div className="text-gray-500 flex flex-col items-center">
                   <div className="flex gap-4 mb-2">
                     <ImageIcon size={32} />
                     <Video size={32} />
                   </div>
                   <p>Dữ liệu hình ảnh/video sẽ hiển thị tại đây</p>
                 </div>
               )}
             </div>
          </div>

          {/* Body: Standards */}
          <div className="flex-grow">
            <TechniqueStandard />
          </div>

        </div>

        {/* RIGHT COLUMN: Analysis Results */}
        <div className="flex flex-col h-full">
          <AnalysisDisplay 
            result={analysisResult} 
            loading={loading}
            onSpeak={handleSpeak}
            onExport={handleExport}
            onReset={handleReset}
            mediaUrl={mediaUrl}
          />
        </div>

      </main>
    </div>
  );
};

export default App;

