          <p className="text-xs font-bold text-red-700 tracking-wider">Chuyên gia AI</p>
        </div>
        <div className="flex gap-2">
          <button 
            onClick={() => onSpeak()} // Calls without args to trigger "Summary + Conclusion" mode
