          <div className="flex items-center gap-2 mb-2">
            <Activity className="text-indigo-600" size={20} />
            <h3 className="text-indigo-800 font-bold uppercase text-sm">NHẬN XÉT QUÁ TRÌNH THỰC HIỆN:</h3>
